/*
 * Umbral — WiFi presence sensing node (ESP32, ESP-IDF 5.x)
 *
 * Each node measures Channel State Information (CSI) on two links:
 *   - router -> this node   (traffic generated by pinging the other node / the gateway)
 *   - other node -> this node (ESP-NOW beacons at 50 Hz, sent at an OFDM rate so CSI is reported)
 * Per link it computes motion metrics and a per-subcarrier motion signature, and serves them
 * as JSON at GET /data (CORS open). GET / serves the web panel embedded from web/index.html.
 *
 * Serial protocol (921600 baud), used by tools/configure-board.html:
 *   PC -> node:  "WIFI\t<ssid>\t<password>\n" | "NAME\t<name>\n" | "FORGET\n" | "INFO\n"
 *   node -> PC:  "STATUS,NEED_WIFI" | "STATUS,CONNECTING,<ssid>" | "STATUS,WIFI_OK,<ip>,<gw>"
 *                "STATUS,WIFI_FAIL,..." | "STATUS,SAVED" | "STATUS,STATS,<pps>,<index*1000>,..."
 *
 * CSI capture setup adapted from espressif/esp-csi (Apache-2.0),
 * examples/get-started/csi_recv_router.
 */
#include <stdio.h>
#include <string.h>
#include <math.h>
#include <stdlib.h>
#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "freertos/event_groups.h"
#include "freertos/semphr.h"
#include "nvs_flash.h"
#include "nvs.h"
#include "esp_mac.h"
#include "esp_system.h"
#include "rom/ets_sys.h"
#include "esp_log.h"
#include "esp_wifi.h"
#include "esp_netif.h"
#include "esp_event.h"
#include "esp_http_server.h"
#include "driver/uart.h"
#include "lwip/inet.h"
#include "ping/ping_sock.h"
#include "lwip/ip4_addr.h"
#include "esp_now.h"
#include "esp_timer.h"

#define PING_HZ   100
#define NSC       64     /* L-LTF subcarriers */
#define WIN       50     /* packets per window (~0.5 s) */
#define GOT_IP_BIT BIT0

extern const char panel_html_start[] asm("_binary_index_html_start");
extern const char panel_html_end[]   asm("_binary_index_html_end");

static EventGroupHandle_t s_ev;
static char s_ssid[33], s_pass[65], s_name[33] = "node";
static char s_ip[16] = "", s_gw[16] = "";
static uint8_t s_bssid[6];
static int s_retries = 0;

/* CSI data per link: 0 = router, 1 = the other node */
#define NLINK 2
#define ESPNOW_HZ 50
typedef struct {
    float ring[WIN][NSC];
    int pos, fill, rssi;
    volatile uint32_t count;
    /* packet format: sig_mode (0 = 11b/g, 1 = 11n) x bandwidth (0 = 20 MHz, 1 = 40 MHz) */
    volatile uint32_t fmt_cnt[4];   /* received per format (cumulative) */
    int fmt_lock;                   /* accepted format; -1 = learning */
    uint32_t fmt_learn[4];
    volatile uint32_t total;        /* received from this sender, any format */
    float amp_last[NSC];
    float index, pps;
    float m[5];          /* alternative metrics (see metric_task) */
    float prof[NSC];     /* fingerprint: mean normalized amplitude over the window */
    float sig[NSC];      /* motion signature: how much each subcarrier varies over the window (std / mean) */
} link_t;
static portMUX_TYPE s_mux = portMUX_INITIALIZER_UNLOCKED;
static link_t s_link[NLINK];

/* the other node (learned from its ESP-NOW packets) */
#define MAGIC "CSIT"
typedef struct __attribute__((packed)) { char magic[4]; char name[33]; char ip[16]; uint32_t seq; } beacon_t;
static uint8_t s_peer_mac[6];
static bool s_peer_known = false;
static char s_peer_name[33] = "", s_peer_ip[16] = "";
static int64_t s_peer_seen_us = 0;

/* ---------- NVS ---------- */
static void nvs_get(const char *key, char *out, size_t len)
{
    nvs_handle_t h;
    if (nvs_open("cfg", NVS_READONLY, &h) != ESP_OK) return;
    size_t l = len;
    if (nvs_get_str(h, key, out, &l) != ESP_OK) { /* keep the default value */ }
    nvs_close(h);
}
static void nvs_put(const char *key, const char *val)
{
    nvs_handle_t h;
    ESP_ERROR_CHECK(nvs_open("cfg", NVS_READWRITE, &h));
    nvs_set_str(h, key, val);
    nvs_commit(h);
    nvs_close(h);
}
static void nvs_forget(void)
{
    nvs_handle_t h;
    if (nvs_open("cfg", NVS_READWRITE, &h) == ESP_OK) { nvs_erase_all(h); nvs_commit(h); nvs_close(h); }
}

/* ---------- serial commands ---------- */
static void uart_cmd_task(void *arg)
{
    static char line[200];
    int n = 0;
    uint8_t c;
    for (;;) {
        if (uart_read_bytes(UART_NUM_0, &c, 1, portMAX_DELAY) != 1) continue;
        if (c == '\r') continue;
        if (c != '\n') { if (n < (int)sizeof(line) - 1) line[n++] = c; continue; }
        line[n] = 0; n = 0;
        if (strncmp(line, "WIFI\t", 5) == 0) {
            char *ssid = line + 5, *tab = strchr(ssid, '\t');
            if (!tab) { ets_printf("STATUS,ERROR,format\n"); continue; }
            *tab = 0;
            const char *pass = tab + 1;
            if (!ssid[0] || strlen(ssid) > 32 || strlen(pass) > 64) { ets_printf("STATUS,ERROR,length\n"); continue; }
            nvs_put("ssid", ssid);
            nvs_put("pass", pass);
            ets_printf("STATUS,SAVED\n");
            vTaskDelay(pdMS_TO_TICKS(300));
            esp_restart();
        } else if (strncmp(line, "NAME\t", 5) == 0) {
            const char *name = line + 5;
            if (!name[0] || strlen(name) > 32) { ets_printf("STATUS,ERROR,name\n"); continue; }
            nvs_put("name", name);
            strncpy(s_name, name, sizeof(s_name) - 1);
            ets_printf("STATUS,NAME_OK,%s\n", s_name);
        } else if (strcmp(line, "FORGET") == 0) {
            nvs_forget();
            ets_printf("STATUS,FORGOTTEN\n");
            vTaskDelay(pdMS_TO_TICKS(300));
            esp_restart();
        } else if (strcmp(line, "INFO") == 0) {
            if (s_ip[0]) ets_printf("STATUS,WIFI_OK,%s,%s\n", s_ip, s_gw);
            else if (!s_ssid[0]) ets_printf("STATUS,NEED_WIFI\n");
            else ets_printf("STATUS,CONNECTING,%s\n", s_ssid);
            ets_printf("STATUS,NAME_OK,%s\n", s_name);
        }
    }
}

/* ---------- CSI ---------- */
static void csi_cb(void *ctx, wifi_csi_info_t *info)
{
    if (!info || !info->buf) return;
    int li;
    if (!memcmp(info->mac, s_bssid, 6)) li = 0;
    else if (s_peer_known && !memcmp(info->mac, s_peer_mac, 6)) li = 1;
    else return;
    link_t *L = &s_link[li];
    int fmt = (info->rx_ctrl.sig_mode ? 2 : 0) + (info->rx_ctrl.cwb ? 1 : 0);
    L->fmt_cnt[fmt]++; L->total++;
    if (L->fmt_lock < 0) {                      /* learn the most common format in the first 150 packets */
        L->fmt_learn[fmt]++;
        uint32_t t = L->fmt_learn[0] + L->fmt_learn[1] + L->fmt_learn[2] + L->fmt_learn[3];
        if (t < 150) return;
        int best = 0; for (int f = 1; f < 4; f++) if (L->fmt_learn[f] > L->fmt_learn[best]) best = f;
        L->fmt_lock = best;
        memset(L->fmt_learn, 0, sizeof(L->fmt_learn));
    }
    if (fmt != L->fmt_lock) return;             /* different format: different fingerprint, discard */
    int n = info->len / 2;
    if (n > NSC) n = NSC;
    float amp[NSC] = {0};
    for (int k = 0; k < n; k++) {
        float im = info->buf[2 * k], re = info->buf[2 * k + 1];
        amp[k] = sqrtf(re * re + im * im);
    }
    int act = 0;
    for (int k = 0; k < n; k++) if (amp[k] > 1) act++;
    if (act < 10) return;
    portENTER_CRITICAL(&s_mux);
    memcpy(L->ring[L->pos], amp, sizeof(amp));
    L->pos = (L->pos + 1) % WIN;
    if (L->fill < WIN) L->fill++;
    memcpy(L->amp_last, amp, sizeof(amp));
    L->rssi = info->rx_ctrl.rssi;
    portEXIT_CRITICAL(&s_mux);
    L->count++;
}

/* robust index:
 * 1) drop the 10% most atypical packets in the window,
 * 2) per subcarrier: mean absolute deviation / mean (on already normalized amplitudes),
 * 3) average, dropping the 10% noisiest subcarriers. */
static int cmpf(const void *a, const void *b) { float x = *(const float *)a, y = *(const float *)b; return (x > y) - (x < y); }

static float link_index(float (*ring)[NSC], int fill)
{
    if (fill < 10) return 0;
    static float mv[NSC], dist[WIN], tmp[WIN], r[NSC];
    static bool keep[WIN];
    for (int k = 0; k < NSC; k++) { float s = 0; for (int i = 0; i < fill; i++) s += ring[i][k]; mv[k] = s / fill; }
    for (int i = 0; i < fill; i++) { float d = 0; for (int k = 0; k < NSC; k++) d += fabsf(ring[i][k] - mv[k]); dist[i] = tmp[i] = d; }
    qsort(tmp, fill, sizeof(float), cmpf);
    float cut = tmp[(fill * 9) / 10];
    int kept = 0;
    for (int i = 0; i < fill; i++) { keep[i] = dist[i] <= cut; kept += keep[i]; }
    if (kept < 8) return 0;
    for (int k = 0; k < NSC; k++) { float s = 0; for (int i = 0; i < fill; i++) if (keep[i]) s += ring[i][k]; mv[k] = s / kept; }
    int nr = 0;
    for (int k = 0; k < NSC; k++) {
        if (mv[k] < 0.2f) continue;            /* null subcarriers */
        float dev = 0;
        for (int i = 0; i < fill; i++) if (keep[i]) dev += fabsf(ring[i][k] - mv[k]);
        r[nr++] = (dev / kept) / mv[k];
    }
    if (nr < 10) return 0;
    qsort(r, nr, sizeof(float), cmpf);
    int use = (nr * 9) / 10; float acc = 0;
    for (int k = 0; k < use; k++) acc += r[k];
    return acc / use;
}

/* m0: the original index (coefficient of variation of the raw amplitude) */
static float m_cv(float (*ring)[NSC], int fill, float floor_)
{
    float acc = 0; int cnt = 0;
    for (int k = 0; k < NSC; k++) {
        float s = 0, s2 = 0;
        for (int i = 0; i < fill; i++) { s += ring[i][k]; s2 += ring[i][k] * ring[i][k]; }
        float m = s / fill;
        if (m < floor_) continue;
        float var = s2 / fill - m * m;
        acc += sqrtf(var > 0 ? var : 0) / m;
        cnt++;
    }
    return cnt ? acc / cnt : 0;
}
/* m3: shape change between consecutive packets: 1 - correlation (gain-insensitive) */
static float m_shape(float (*nr)[NSC], int fill)
{
    float acc = 0; int cnt = 0;
    for (int i = 1; i < fill; i++) {
        float sa = 0, sb = 0, n = 0;
        for (int k = 0; k < NSC; k++) if (nr[i][k] > 0.2f && nr[i-1][k] > 0.2f) { sa += nr[i][k]; sb += nr[i-1][k]; n++; }
        if (n < 10) continue;
        float ma = sa / n, mb = sb / n, sab = 0, saa = 0, sbb = 0;
        for (int k = 0; k < NSC; k++) if (nr[i][k] > 0.2f && nr[i-1][k] > 0.2f) {
            float x = nr[i][k] - ma, y = nr[i-1][k] - mb; sab += x * y; saa += x * x; sbb += y * y; }
        if (saa <= 0 || sbb <= 0) continue;
        acc += 1.0f - sab / sqrtf(saa * sbb); cnt++;
    }
    return cnt ? 10.0f * acc / cnt : 0;
}
/* m4: variation of total packet power */
static float m_power(float (*ring)[NSC], int fill)
{
    float s = 0, s2 = 0;
    for (int i = 0; i < fill; i++) { float p = 0; for (int k = 0; k < NSC; k++) p += ring[i][k]; s += p; s2 += p * p; }
    float m = s / fill; if (m <= 0) return 0;
    float v = s2 / fill - m * m;
    return sqrtf(v > 0 ? v : 0) / m;
}

static void ping_watchdog(void);
static void metric_task(void *arg)
{
    TickType_t last_sec = xTaskGetTickCount();
    uint32_t last_cnt[NLINK] = {0};
    for (;;) {
        vTaskDelay(pdMS_TO_TICKS(100));
        for (int li = 0; li < NLINK; li++) {
            static float raw[WIN][NSC], nr[WIN][NSC];
            int fill, pos;
            portENTER_CRITICAL(&s_mux);
            fill = s_link[li].fill; pos = s_link[li].pos;
            for (int i = 0; i < fill; i++) memcpy(raw[i], s_link[li].ring[(pos - fill + i + WIN) % WIN], sizeof(raw[i]));
            portEXIT_CRITICAL(&s_mux);
            float mm[5] = {0};
            if (fill >= 10) {
                for (int i = 0; i < fill; i++) {
                    float sum = 0; int act = 0;
                    for (int k = 0; k < NSC; k++) if (raw[i][k] > 1) { sum += raw[i][k]; act++; }
                    float inv = (act && sum > 0) ? act / sum : 0;
                    for (int k = 0; k < NSC; k++) nr[i][k] = raw[i][k] * inv;
                }
                mm[0] = m_cv(raw, fill, 2.0f);
                mm[1] = link_index(nr, fill);
                mm[2] = m_cv(nr, fill, 0.2f);
                mm[3] = m_shape(nr, fill);
                mm[4] = m_power(raw, fill);
            }
            if (fill >= 10) {
                float pr[NSC];
                float sg[NSC];
                for (int k = 0; k < NSC; k++) {
                    float acc = 0, acc2 = 0;
                    for (int i = 0; i < fill; i++) { acc += nr[i][k]; acc2 += nr[i][k] * nr[i][k]; }
                    pr[k] = acc / fill;
                    float var = acc2 / fill - pr[k] * pr[k];
                    sg[k] = pr[k] > 0.2f ? sqrtf(var > 0 ? var : 0) / pr[k] : 0;
                }
                portENTER_CRITICAL(&s_mux); memcpy(s_link[li].prof, pr, sizeof(pr)); memcpy(s_link[li].sig, sg, sizeof(sg)); portEXIT_CRITICAL(&s_mux);
            }
            static float hist[NLINK][5][5]; static int hpos[NLINK];
            for (int j = 0; j < 5; j++) {
                hist[li][j][hpos[li]] = mm[j];
                float h[5]; memcpy(h, hist[li][j], sizeof(h)); qsort(h, 5, sizeof(float), cmpf);
                s_link[li].m[j] = h[2];          /* median of the last 0.5 s */
            }
            hpos[li] = (hpos[li] + 1) % 5;
            s_link[li].index = s_link[li].m[0];
        }
        TickType_t now = xTaskGetTickCount();
        if (now - last_sec >= pdMS_TO_TICKS(1000)) {
            float dt = pdTICKS_TO_MS(now - last_sec) / 1000.0f;
            for (int li = 0; li < NLINK; li++) {
                uint32_t c = s_link[li].count;
                s_link[li].pps = (c - last_cnt[li]) / dt;
                static uint32_t last_tot[NLINK];
                uint32_t tot = s_link[li].total; float tps = (tot - last_tot[li]) / dt; last_tot[li] = tot;
                if (s_link[li].fmt_lock >= 0 && s_link[li].pps < 3 && tps > 20) {   /* the sender changed format: relearn */
                    s_link[li].fmt_lock = -1; memset(s_link[li].fmt_learn, 0, sizeof(s_link[li].fmt_learn));
                }
                last_cnt[li] = c;
                /* if a link stops receiving packets, clear its window */
                if (s_link[li].pps < 1) { portENTER_CRITICAL(&s_mux); s_link[li].fill = 0; portEXIT_CRITICAL(&s_mux); s_link[li].index = 0; }
            }
            last_sec = now;
            ping_watchdog();
            ets_printf("STATUS,STATS,%d,%d,%d,%d,%s\n", (int)s_link[0].pps, (int)(s_link[0].index * 1000),
                       (int)s_link[1].pps, (int)(s_link[1].index * 1000), s_peer_known ? s_peer_name : "-");
        }
    }
}

/* ---------- ESP-NOW between nodes ---------- */
static void espnow_recv_cb(const esp_now_recv_info_t *info, const uint8_t *data, int len)
{
    if (len < (int)sizeof(beacon_t) || memcmp(data, MAGIC, 4)) return;
    const beacon_t *b = (const beacon_t *)data;
    if (!s_peer_known || memcmp(s_peer_mac, info->src_addr, 6)) {
        memcpy(s_peer_mac, info->src_addr, 6);
        s_peer_known = true;
    }
    memcpy(s_peer_name, b->name, sizeof(s_peer_name)); s_peer_name[32] = 0;
    memcpy(s_peer_ip, b->ip, sizeof(s_peer_ip)); s_peer_ip[15] = 0;
    s_peer_seen_us = esp_timer_get_time();
}

static void espnow_task(void *arg)
{
    static const uint8_t bcast[6] = {0xff, 0xff, 0xff, 0xff, 0xff, 0xff};
    ESP_ERROR_CHECK(esp_now_init());
    ESP_ERROR_CHECK(esp_now_register_recv_cb(espnow_recv_cb));
    esp_now_peer_info_t peer = { .channel = 0, .ifidx = WIFI_IF_STA, .encrypt = false };
    memcpy(peer.peer_addr, bcast, 6);
    ESP_ERROR_CHECK(esp_now_add_peer(&peer));
    /* OFDM rate (MCS0) so the receiver gets CSI; at 1 Mbps (DSSS) there is no CSI */
    esp_now_rate_config_t rc = { .phymode = WIFI_PHY_MODE_HT20, .rate = WIFI_PHY_RATE_MCS0_LGI, .ersu = false, .dcm = false };
    esp_now_set_peer_rate_config(bcast, &rc);
    beacon_t b = {0};
    memcpy(b.magic, MAGIC, 4);
    TickType_t last = xTaskGetTickCount();
    for (;;) {
        strncpy(b.name, s_name, sizeof(b.name) - 1);
        strncpy(b.ip, s_ip, sizeof(b.ip) - 1);
        b.seq++;
        esp_now_send(bcast, (const uint8_t *)&b, sizeof(b));
        vTaskDelayUntil(&last, pdMS_TO_TICKS(1000 / ESPNOW_HZ));
    }
}

static void csi_start(void)
{
    wifi_ap_record_t ap = {0};
    ESP_ERROR_CHECK(esp_wifi_sta_get_ap_info(&ap));
    memcpy(s_bssid, ap.bssid, 6);
    wifi_csi_config_t cfg = {
        .lltf_en = true, .htltf_en = false, .stbc_htltf2_en = false,
        .ltf_merge_en = true, .channel_filter_en = true, .manu_scale = true, .shift = true,
    };
    ESP_ERROR_CHECK(esp_wifi_set_csi_config(&cfg));
    ESP_ERROR_CHECK(esp_wifi_set_csi_rx_cb(csi_cb, NULL));
    ESP_ERROR_CHECK(esp_wifi_set_csi(true));
}

/* Pings generate traffic transmitted from the router's antenna to this node.
 * We prefer pinging the OTHER node: the router only forwards (no rate limiting as when it replies itself),
 * and both the other node's request and the reply arrive transmitted by the router.
 * If no other node is known, ping the router. */
static esp_ping_handle_t s_ping = NULL;
static uint32_t s_ping_target = 0;
static void ping_to(uint32_t addr)
{
    if (s_ping) { esp_ping_stop(s_ping); esp_ping_delete_session(s_ping); s_ping = NULL; }
    esp_ping_config_t pc = ESP_PING_DEFAULT_CONFIG();
    pc.count = 0;
    pc.interval_ms = 1000 / PING_HZ;
    pc.timeout_ms = 500;
    pc.task_stack_size = 3072;
    pc.data_size = 1;
    pc.target_addr.u_addr.ip4.addr = addr;
    pc.target_addr.type = ESP_IPADDR_TYPE_V4;
    esp_ping_callbacks_t cbs = {0};
    if (esp_ping_new_session(&pc, &cbs, &s_ping) == ESP_OK) { esp_ping_start(s_ping); s_ping_target = addr; }
    ets_printf("STATUS,PING," IPSTR "\n", IP2STR((esp_ip4_addr_t *)&addr));
}
static uint32_t gw_addr(void)
{
    esp_netif_ip_info_t ip;
    esp_netif_get_ip_info(esp_netif_get_handle_from_ifkey("WIFI_STA_DEF"), &ip);
    return ip.gw.addr;
}
static uint32_t peer_addr(void)
{
    if (!s_peer_known || !s_peer_ip[0]) return 0;
    if ((esp_timer_get_time() - s_peer_seen_us) > 5000000) return 0;
    return ipaddr_addr(s_peer_ip);
}
static void ping_start(void) { ping_to(gw_addr()); }

/* every second: target the other node once it appears, and restart if packets stop */
static void ping_watchdog(void)
{
    static int starving = 0;
    uint32_t peer = peer_addr(), gw = gw_addr();
    if (peer && peer != IPADDR_NONE && s_ping_target != peer && starving == 0) { ping_to(peer); return; }
    if (s_link[0].pps < 5) starving++; else starving = 0;
    if (starving >= 5) {                      /* 5 s without router packets: switch target */
        uint32_t next = (s_ping_target == gw && peer && peer != IPADDR_NONE) ? peer : gw;
        ping_to(next);
        starving = -10;                       /* wait 10 s before re-evaluating */
    }
}

/* ---------- HTTP ---------- */
static esp_err_t h_root(httpd_req_t *req)
{
    httpd_resp_set_type(req, "text/html; charset=utf-8");
    return httpd_resp_send(req, panel_html_start, panel_html_end - panel_html_start);
}

static esp_err_t h_data(httpd_req_t *req)
{
    static char buf[3200];
    static float amp[NLINK][NSC], sgv[NLINK][NSC]; int rssi[NLINK];
    portENTER_CRITICAL(&s_mux);
    for (int li = 0; li < NLINK; li++) { memcpy(amp[li], s_link[li].prof, sizeof(amp[li])); memcpy(sgv[li], s_link[li].sig, sizeof(sgv[li])); rssi[li] = s_link[li].rssi; }
    portEXIT_CRITICAL(&s_mux);
    int age = s_peer_known ? (int)((esp_timer_get_time() - s_peer_seen_us) / 1000) : -1;
    int o = snprintf(buf, sizeof(buf),
        "{\"name\":\"%s\",\"ip\":\"%s\",\"peer\":{\"name\":\"%s\",\"ip\":\"%s\",\"age_ms\":%d},\"links\":[",
        s_name, s_ip, s_peer_name, s_peer_ip, age);
    static const char *ids[NLINK] = {"router", "peer"};
    for (int li = 0; li < NLINK; li++) {
        const float *m = s_link[li].m;
        o += snprintf(buf + o, sizeof(buf) - o, "%s{\"id\":\"%s\",\"index\":%.4f,\"m\":[%.4f,%.4f,%.4f,%.4f,%.4f],\"pps\":%d,\"rssi\":%d,\"fmt\":[%lu,%lu,%lu,%lu],\"lock\":%d,\"p\":[",
                      li ? "," : "", ids[li], s_link[li].index, m[0], m[1], m[2], m[3], m[4], (int)s_link[li].pps, rssi[li],
                      (unsigned long)s_link[li].fmt_cnt[0], (unsigned long)s_link[li].fmt_cnt[1], (unsigned long)s_link[li].fmt_cnt[2], (unsigned long)s_link[li].fmt_cnt[3],
                      s_link[li].fmt_lock);
        for (int k = 0; k < NSC && o < (int)sizeof(buf) - 16; k++)
            o += snprintf(buf + o, sizeof(buf) - o, k ? ",%d" : "%d", (int)(amp[li][k] * 1000 + 0.5f));
        o += snprintf(buf + o, sizeof(buf) - o, "],\"s\":[");
        for (int k = 0; k < NSC && o < (int)sizeof(buf) - 16; k++)
            o += snprintf(buf + o, sizeof(buf) - o, k ? ",%d" : "%d", (int)(sgv[li][k] * 10000 + 0.5f));
        o += snprintf(buf + o, sizeof(buf) - o, "]}");
    }
    o += snprintf(buf + o, sizeof(buf) - o, "]}");
    httpd_resp_set_type(req, "application/json");
    httpd_resp_set_hdr(req, "Access-Control-Allow-Origin", "*");
    httpd_resp_set_hdr(req, "Cache-Control", "no-store");
    return httpd_resp_send(req, buf, o);
}

static void http_start(void)
{
    httpd_config_t cfg = HTTPD_DEFAULT_CONFIG();
    cfg.lru_purge_enable = true;
    cfg.max_open_sockets = 7;
    httpd_handle_t srv = NULL;
    ESP_ERROR_CHECK(httpd_start(&srv, &cfg));
    httpd_uri_t u1 = { .uri = "/", .method = HTTP_GET, .handler = h_root };
    httpd_uri_t u2 = { .uri = "/data", .method = HTTP_GET, .handler = h_data };
    httpd_register_uri_handler(srv, &u1);
    httpd_register_uri_handler(srv, &u2);
}

/* ---------- WiFi ---------- */
static void reconnect_task(void *arg)
{
    vTaskDelay(pdMS_TO_TICKS(2000));
    esp_wifi_connect();
    vTaskDelete(NULL);
}

static void on_event(void *arg, esp_event_base_t base, int32_t id, void *data)
{
    if (base == WIFI_EVENT && id == WIFI_EVENT_STA_START) {
        esp_wifi_connect();
    } else if (base == WIFI_EVENT && id == WIFI_EVENT_STA_DISCONNECTED) {
        wifi_event_sta_disconnected_t *d = data;
        s_retries++;
        s_ip[0] = 0;
        ets_printf("STATUS,WIFI_FAIL,reason=%d,attempt=%d\n", d->reason, s_retries);
        xTaskCreate(reconnect_task, "reconn", 2048, NULL, 3, NULL);
    } else if (base == IP_EVENT && id == IP_EVENT_STA_GOT_IP) {
        ip_event_got_ip_t *e = data;
        s_retries = 0;
        snprintf(s_ip, sizeof(s_ip), IPSTR, IP2STR(&e->ip_info.ip));
        snprintf(s_gw, sizeof(s_gw), IPSTR, IP2STR(&e->ip_info.gw));
        ets_printf("STATUS,WIFI_OK,%s,%s\n", s_ip, s_gw);
        xEventGroupSetBits(s_ev, GOT_IP_BIT);
    }
}

void app_main(void)
{
    esp_log_level_set("*", ESP_LOG_WARN);
    esp_err_t r = nvs_flash_init();
    if (r == ESP_ERR_NVS_NO_FREE_PAGES || r == ESP_ERR_NVS_NEW_VERSION_FOUND) {
        ESP_ERROR_CHECK(nvs_flash_erase());
        r = nvs_flash_init();
    }
    ESP_ERROR_CHECK(r);

    ESP_ERROR_CHECK(uart_driver_install(UART_NUM_0, 1024, 0, 0, NULL, 0));
    xTaskCreate(uart_cmd_task, "uart_cmd", 4096, NULL, 5, NULL);

    nvs_get("ssid", s_ssid, sizeof(s_ssid));
    nvs_get("pass", s_pass, sizeof(s_pass));
    nvs_get("name", s_name, sizeof(s_name));
    if (!s_ssid[0]) {
        for (;;) { ets_printf("STATUS,NEED_WIFI\n"); vTaskDelay(pdMS_TO_TICKS(2000)); }
    }

    s_ev = xEventGroupCreate();
    ESP_ERROR_CHECK(esp_netif_init());
    ESP_ERROR_CHECK(esp_event_loop_create_default());
    esp_netif_t *netif = esp_netif_create_default_wifi_sta();
    char host[40];
    snprintf(host, sizeof(host), "csi-%s", s_name);
    for (char *p = host; *p; p++) if (!((*p >= 'a' && *p <= 'z') || (*p >= 'A' && *p <= 'Z') || (*p >= '0' && *p <= '9'))) *p = '-';
    esp_netif_set_hostname(netif, host);

    wifi_init_config_t ic = WIFI_INIT_CONFIG_DEFAULT();
    ESP_ERROR_CHECK(esp_wifi_init(&ic));
    ESP_ERROR_CHECK(esp_event_handler_register(WIFI_EVENT, ESP_EVENT_ANY_ID, on_event, NULL));
    ESP_ERROR_CHECK(esp_event_handler_register(IP_EVENT, IP_EVENT_STA_GOT_IP, on_event, NULL));
    ESP_ERROR_CHECK(esp_wifi_set_storage(WIFI_STORAGE_RAM));
    ESP_ERROR_CHECK(esp_wifi_set_mode(WIFI_MODE_STA));
    wifi_config_t wc = {0};
    strncpy((char *)wc.sta.ssid, s_ssid, sizeof(wc.sta.ssid));
    strncpy((char *)wc.sta.password, s_pass, sizeof(wc.sta.password));
    wc.sta.threshold.authmode = WIFI_AUTH_OPEN;
    ESP_ERROR_CHECK(esp_wifi_set_config(WIFI_IF_STA, &wc));
    ets_printf("STATUS,CONNECTING,%s\n", s_ssid);
    ESP_ERROR_CHECK(esp_wifi_start());
    ESP_ERROR_CHECK(esp_wifi_set_ps(WIFI_PS_NONE));
    esp_wifi_set_max_tx_power(60);   /* ~15 dBm: trade-off between power draw and node-to-node range */

    xEventGroupWaitBits(s_ev, GOT_IP_BIT, pdFALSE, pdTRUE, portMAX_DELAY);
    for (int li = 0; li < NLINK; li++) s_link[li].fmt_lock = -1;
    csi_start();
    ping_start();
    http_start();
    xTaskCreate(espnow_task, "espnow", 4096, NULL, 4, NULL);
    xTaskCreate(metric_task, "metric", 6144, NULL, 4, NULL);
}
